    """Count islands (connected components of 1s) in a binary grid.
    Connectivity is 4-directional.
    """
    if not grid:
        return 0
    n = len(grid)
    m = len(grid[0])
    visited = [[False] * m for _ in range(n)]
    count = 0
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if x < 0 or x >= n or y < 0 or y >= m:
                continue
            if visited[x][y] or grid[x][y] == 0:
                continue
            visited[x][y] = True
            stack.extend([(x-1, y), (x+1, y), (x, y-1), (x, y+1)])
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                dfs(i, j)
    return count"}

